{
  "id": "R3",
  "summary_ko": "럭비공이 물리 법칙을 거스르며 던진 사람 쪽으로 부메랑처럼 되돌아옵니다.",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "The rugby ball boomerangs back towards the person throwing it defying the laws of physics.",
      "symptom_ko": "럭비공이 물리 법칙을 무시하고 던진 사람을 향해 부메랑처럼 되돌아옴",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The rugby ball",
      "explicit_detail_evidence": [
        "boomerangs back towards the person throwing it",
        "defying the laws of physics"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "target_relation": "same",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The ball doesn't move naturally",
      "candidate_evidence": "The ball shifts shape and surface patterns inconsistently between soccer ball markings and football laces while moving and rolling.",
      "basis": "insufficient",
      "reason_ko": "참조 설명은 '공의 움직임이 자연스럽지 않다'는 매우 포괄적인(broad) 결함만을 서술하고 있습니다. 후보는 공이 구르고 움직이는 동안 발생하는 구체적인 형태 및 표면 변형 현상을 설명하고 있으며, 참조의 포괄적 서술이 이 구체적인 현상을 포괄하는 것인지 아니면 별개의 물리적 궤적 결함을 의미하는지 텍스트만으로는 판별할 수 없어 보류(insufficient) 처리합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "same",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The ball doesn't move naturally",
      "candidate_evidence": "The rolling ball continuously morphs its geometry and surface markings, changing between a rugby/American football shape and a round soccer ball shape while rolling along the grass.",
      "basis": "insufficient",
      "reason_ko": "동일한 대상인 공에 대해 참조는 움직임이 부자연스럽다는 포괄적인 결함만 언급한 반면, 후보는 구르는 동안의 형상 변형(모핑)이라는 구체적인 결함을 제시하고 있습니다. 포괄적 참조와 구체적 후보 간의 범주 차이만으로는 배제할 수 없으며 명시적 모순이 없으므로 일치 여부를 판단하기에 정보가 부족합니다."
    }
  ]
}

